type Props = {
  className?: string;
  forExport?: boolean;
  generateRef?: React.RefObject<() => Promise<HTMLCanvasElement>>;
};

const WIDTH = 270;
const HEIGHT = 480;

const EXPORT_WIDTH = WIDTH * 4;
const EXPORT_HEIGHT = HEIGHT * 4;

export function ShareImage(props: Props) {
  const state = useShareState();
  const ref = useRef<HTMLDivElement>(null!);

  const theme = ColourThemes[state.theme];

  const noteText = state.includeNote ? state.note.trim() : null;

  const [scaleFactor, setScaleFactor] = useState(1);

  useLayoutEffect(() => {
    const updateSize = () => {
      setScaleFactor(ref.current.offsetWidth / WIDTH);
    };
    updateSize();

    const ro = new ResizeObserver(() => {
      updateSize();
    });
    ro.observe(ref.current);
    return () => {
      ro.disconnect();
    };
  }, []);

  const img = state.images[state.selectedImageIndex];

  const croppedImage = useMemo(() => {
    if (!img) return null;

    const TARGET_WIDTH = 720;
    const TARGET_HEIGHT = 960;

    const canvas = cropImage(img, TARGET_WIDTH, TARGET_HEIGHT);

    return canvas.toDataURL();
  }, [img]);

  if (props.generateRef) {
    props.generateRef.current = async () => {
      const canvas = await html2canvas(ref.current, {
        scale: 1,
        backgroundColor: theme.bg,
      });
      return cropImage(canvas, EXPORT_WIDTH, EXPORT_HEIGHT);
    };
  }

  // useEffect(() => {
  //   const generate = async () => {
  //     const canvas = await html2canvas(ref.current, {
  //       scale: 5,
  //       backgroundColor: theme.bg,
  //     });
  //     canvas.toBlob((blob) => {
  //       if (blob) {
  //         const url = URL.createObjectURL(blob);
  //         const a = document.createElement("a");
  //         a.href = url;
  //         a.download = "share-image.png";
  //         a.click();
  //         URL.revokeObjectURL(url);
  //       }
  //     });
  //   };
  //   const signal = new AbortController();

  //   window.addEventListener(
  //     "keydown",
  //     (e) => {
  //       if (e.key === "s" && (e.metaKey || e.ctrlKey)) {
  //         e.preventDefault();
  //         generate();
  //       }
  //     },
  //     { signal: signal.signal },
  //   );

  //   return () => {
  //     signal.abort();
  //   };
  // }, [theme]);

  return (
    <div
      className={cn("absolute size-full border break-words", props.className)}
      ref={ref}
      style={
        {
          backgroundColor: theme.bg,
          "--scale": `${scaleFactor}`,
          ...(props.forExport
            ? {
                width: EXPORT_WIDTH,
                height: EXPORT_HEIGHT,
                border: "0",
              }
            : {
                aspectRatio: WIDTH / HEIGHT,
                borderColor: theme.preview[1],
              }),
        } as any
      }
    >
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <Parts.Line color={theme.line} className="w-full h-auto" />
      </div>

      <div className="absolute inset-y-[10%] inset-x-[10%] flex flex-col items-center justify-center gap-[calc(var(--scale)*16px)]">
        <div className="pr-[calc(var(--scale)*15px)] w-full flex justify-center">
          <Parts.Header
            color={theme.text}
            className={cn("h-auto", !!noteText ? "w-[85%]" : "w-[90%]")}
          />
        </div>

        {croppedImage && (
          <img
            src={croppedImage}
            className={cn(
              "relative aspect-[72/96] rounded-[calc(var(--scale)*14px)] overflow-hidden",
              !!noteText ? "w-[50%]" : "w-[60%]",
            )}
            style={{
              transform: "rotate(-8deg)",
            }}
          />
        )}

        {!!noteText ? (
          <div
            className="text-center w-full text-balance leading-[1] pt-[calc(var(--scale)*9px)]"
            style={{
              color: theme.text,
              fontSize:
                scaleFactor *
                  mapRange(
                    noteText.length,
                    0,
                    200,
                    img ? 20 : 25,
                    img ? 12 : 14,
                    false,
                  ) +
                "px",
            }}
          >
            “{noteText}”
          </div>
        ) : (
          <div className="flex items-center justify-center w-full mt-[calc(var(--scale)*16px)]">
            <Parts.TryForYourself
              color={theme.text}
              className="w-[80%] h-auto"
            />
          </div>
        )}
      </div>

      <div className="absolute bottom-[calc(var(--scale)*16px)] w-full flex justify-center">
        <Parts.Footer color={theme.text} className="w-[30%] h-auto" />
      </div>

      {/* <svg
        width={WIDTH}
        height={HEIGHT}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className={cn(
          "absolute top-0 left-0 w-full h-auto object-cover border-[1px]",
          props.className,
        )}
        style={{ borderColor: theme.preview[1] }}
      >
        <rect width={WIDTH} height={HEIGHT} fill={theme.bg} />
        <Parts.Line color={theme.line} />

        {noteText && (
          <text
            x="50%"
            y="40"
            textAnchor="middle"
            fill={theme.text}
            fontSize="24"
            fontWeight="bold"
            fontFamily="sans-serif"
            width={100}
          >
            {noteText}
          </text>
        )}
      </svg> */}
    </div>
  );
}
